{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/hero-split-media.json
    What HeroSplit shows beside the text: a picture, a picture with a floating card, a grid of four pictures with captions, or a picture with two plan cards floating over it.
    Props (p): content, alt, media. *}
{var $v_content = ($p['content'] ?? null)}
{var $v_alt = ($p['alt'] ?? null)}
{var $v_media = ($p['media'] ?? 'picture')}
{if ui_t(ui_eq($v_media, 'picture'))}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_alt, 'ratio' => '4/3']])|noescape}
{/if}
{if ui_t(ui_eq($v_media, 'card'))}
  {=ui_include('blocks/offer-media.latte', ['p' => ['alt' => $v_alt, 'card' => ui_get($v_content, ['card'])]])|noescape}
{/if}
{if ui_t(ui_eq($v_media, 'grid'))}
  {capture $c_3}
    {foreach ui_l(ui_get($v_content, ['features'])) as $v_f}
      {var $v_i = $iterator->counter0}
      {if ui_t(ui_lt($v_i, 4))}
        {capture $c_2}
          {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_f, ['title']), 'ratio' => '1/1']])|noescape}
          {capture $c_1}
            {=ui_text(ui_get($v_f, ['title']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_1])|noescape}
        {/capture}
        {=ui_include('blocks/figure-block.latte', ['p' => ['className' => ui_cnv(['flex flex-col gap-2']), 'testid' => 'hero-tile'], 'children' => $c_2])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'grid grid-cols-2 gap-4', 'Attrs' => ui_attrs(['data-testid', 'hero-grid'])], 'children' => $c_3])|noescape}
{/if}
{if ui_t(ui_eq($v_media, 'plans'))}
  {capture $c_8}
    {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_alt, 'ratio' => '4/3']])|noescape}
    {foreach ui_l(ui_get($v_content, ['plans'])) as $v_p}
      {var $v_i = $iterator->counter0}
      {if ui_t(ui_lt($v_i, 2))}
        {capture $c_7}
          {capture $c_4}
            {=ui_text(ui_get($v_p, ['name']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_4])|noescape}
          {capture $c_6}
            {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'check', 'Size' => 16]])|noescape}
            {capture $c_5}
              {=ui_text(ui_get($v_p, ['tagline']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
          {/capture}
          {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center'], 'children' => $c_6])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => ui_s(ui_cnv(['absolute w-48 rounded bg-card p-4 shadow-lg', (ui_t(ui_eq($v_i, 0)) ? 'top-8 left-4' : 'right-4 bottom-8')])), 'Attrs' => ui_attrs(['data-testid', 'hero-plan'])], 'children' => $c_7])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'relative', 'Attrs' => ui_attrs(['data-testid', 'hero-media'])], 'children' => $c_8])|noescape}
{/if}
